        fullEpisode=Environment.GetEnvironmentVariable("HYBRID_FULL_EPISODE")=="1";reconstructionEpisode=Environment.GetEnvironmentVariable("HYBRID_STAGE_C_RECONSTRUCTION")=="1";targetLateral=EnvFloat("HYBRID_TARGET_LATERAL_M",0);targetMass=EnvFloat("HYBRID_TARGET_MASS_KG",.035f);targetFriction=EnvFloat("HYBRID_TARGET_FRICTION",1);Steps=fullEpisode?56*240:reconstructionEpisode?8*240:2400;Directory.CreateDirectory(Output);Directory.CreateDirectory(Path.Combine(Output,"frames"));
        Build();var camera=BuildCamera();var rows=new List<TraceRow>();
