            priorRight=right.position;priorLeft=left.position;
            maxHeight=Mathf.Max(maxHeight,target.position.y-initialTarget.y);float turnStart=fullEpisode?6+5.2f*3.3f:reconstructionEpisode?4.4f:5.2f,turnEnd=fullEpisode?6+6.5f*3.3f:reconstructionEpisode?5.4f:6.5f;if(t>=turnStart&&t<turnStart+Dt*1.1f)turnReference=target.rotation;if(t>=turnStart&&t<=turnEnd)rotationDeg=Mathf.Max(rotationDeg,Quaternion.Angle(turnReference,target.rotation));
