                right_palm_position_m=right.position+VisualOffset,left_palm_position_m=left.position+VisualOffset,right_palm_rotation=right.rotation,left_palm_rotation=left.rotation,right_closure=Closure(rightDigits),left_closure=Closure(leftDigits),right_digit_closures=rightDigits.Select(x=>x.value).ToArray(),left_digit_closures=leftDigits.Select(x=>x.value).ToArray(),
                right_digit_segments=SegmentSamples("right",rightDigits,priorSegmentPositions,priorSegmentRotations),left_digit_segments=SegmentSamples("left",leftDigits,priorSegmentPositions,priorSegmentRotations),contacts=FrameContacts(step),avatar_root_position_m=Vector3.zero,avatar_root_rotation=Quaternion.identity,torso_local_delta=torso,neck_local_delta=neck,head_local_delta=head,
                right_contact_recovery=rightDigits.Any(x=>x.recovering),left_contact_recovery=leftDigits.Any(x=>x.recovering),measured_contact_count=Contacts.Count(x=>x.step>=step-7),object_sleeping=target.IsSleeping()});if(!fullEpisode&&!reconstructionEpisode)Capture(camera,Path.Combine(Output,"frames",$"frame_{step/8:D4}.png"));}
